import numpy as np
from llm_apps_ops_l1 import fit_tfidf, embed


def cosine(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    na, nb = np.linalg.norm(a), np.linalg.norm(b)
    if na == 0 or nb == 0:
        return 0.0
    return float(a @ b / (na * nb))


def rank(query, docs, stop_words=()):
    model = fit_tfidf(docs, stop_words)
    q = embed(query, model, stop_words)
    if not q.any():
        return []
    scores = [cosine(q, row) for row in model['X']]
    return sorted(reversed(range(len(docs))), key=lambda i: -scores[i])
